using Jellyfin.Plugin.DualSubs.Services;

namespace Jellyfin.Plugin.DualSubs.Tests;

public class PluginFileDetectorTests
{
    [Fact]
    public void ReadsOwnershipMetadata()
    {
        var path = Path.Combine(Path.GetTempPath(), $"dualsubs-{Guid.NewGuid():N}.ass");
        File.WriteAllText(path, """
            [Script Info]
            ; Generated by Jellyfin DualSubs
            ; DualSubs-Version: 1
            ; DualSubs-Pair: eng+spa
            ; DualSubs-SourceHash: abc123
            ; DualSubs-OffsetMs: -2300
            Title: Dual ENG/SPA
            """);

        try
        {
            var file = PluginFileDetector.TryRead(path);

            Assert.NotNull(file);
            Assert.Equal("eng+spa", file.Pair);
            Assert.Equal("abc123", file.SourceHash);
            Assert.Equal(-2300, file.OffsetMs);
        }
        finally
        {
            File.Delete(path);
        }
    }

    [Fact]
    public void IgnoresFilesWithoutMarker()
    {
        var path = Path.Combine(Path.GetTempPath(), $"dualsubs-{Guid.NewGuid():N}.ass");
        File.WriteAllText(path, "[Script Info]\nTitle: User file\n");

        try
        {
            Assert.Null(PluginFileDetector.TryRead(path));
        }
        finally
        {
            File.Delete(path);
        }
    }

    [Fact]
    public void MissingFileReturnsNull()
    {
        Assert.Null(PluginFileDetector.TryRead("/definitely/not/here.ass"));
        Assert.Null(PluginFileDetector.TryRead(null));
    }
}
